// Standalone axisymmetric two-distribution Rykov DVM (model of Wu et al., J. Fluid Mech. 2015) for a normal shock
// at a given Mach number. Build: g++ -O3 -fopenmp -std=c++17 -o rykov_shock rykov_shock.cpp
#include <algorithm>
#include <chrono>
#include <cmath>
#include <csignal>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>
#include <omp.h>
namespace fs=std::filesystem; using V=std::vector<double>; volatile sig_atomic_t stop_flag=0;
void stopped(int){stop_flag=1;}
constexpr double PI=3.14159265358979323846,Z=3.161590375939849,DELTA=.7518796992481203,W0=.49459312747438444,W1=1.957351165625914,OMEGA=.74;
double U1=std::sqrt(5.6),R2=8./3.,T2=27./16.,U2=3.*U1/8.,EF=U1*(.5*U1*U1+3.5),LDOM=30,WIDTH=6;   // Rankine-Hugoniot states of gamma = 7/5, set from --mach
struct Grid{int K;V v,r,w;Grid(const std::string& path){std::ifstream f(path);if(!(f>>K)||K<1)throw std::runtime_error("grid header");v.resize(K);r.resize(K);w.resize(K);for(int j=0;j<K;j++)if(!(f>>v[j]>>r[j]>>w[j])||w[j]<=0)throw std::runtime_error("grid values");}};
struct Mom{double rho,u,tt,tr,qt,qr,tau;};
double M(double rho,double u,double t,double v,double r){return rho/std::pow(2*PI*t,1.5)*std::exp(-((v-u)*(v-u)+r*r)/(2*t));}
Mom moments(const double*F,const double*H,const Grid&g){Mom m{};double p=0;for(int j=0;j<g.K;j++){m.rho+=g.w[j]*F[j];p+=g.w[j]*g.v[j]*F[j];}if(!(m.rho>0&&std::isfinite(m.rho)))throw std::runtime_error("nonpositive/nonfinite rho");m.u=p/m.rho;for(int j=0;j<g.K;j++){double cx=g.v[j]-m.u,e=cx*cx+g.r[j]*g.r[j];m.tt+=g.w[j]*e*F[j];m.tr+=g.w[j]*H[j];m.qt+=.5*g.w[j]*cx*e*F[j];m.qr+=g.w[j]*cx*H[j];}m.tt/=3*m.rho;m.tr/=m.rho;if(!(m.tt>0&&m.tr>0&&std::isfinite(m.tt)&&std::isfinite(m.tr)))throw std::runtime_error("nonpositive/nonfinite temperatures");m.tau=std::pow(m.tt,OMEGA-1)/m.rho;return m;}
void targets(const Mom&m,double v,double r,double &ft,double &ht,double &fr,double &hr){double t=(3*m.tt+2*m.tr)/5,c=v-m.u,e=c*c+r*r,mt=M(m.rho,m.u,m.tt,v,r),mr=M(m.rho,m.u,t,v,r);ft=mt*(1+m.qt*c*(e-5*m.tt)/(15*m.rho*std::pow(m.tt,3)));fr=mr*(1+W0*m.qt*c*(e-5*t)/(15*m.rho*std::pow(t,3)));ht=m.tr*ft+mt*(1-DELTA)*m.qr*c/(m.rho*m.tt);hr=t*fr+mr*W1*(1-DELTA)*m.qr*c/(m.rho*t);}
double mm(double a,double b,double c){if(a>0&&b>0&&c>0)return std::min({a,b,c});if(a<0&&b<0&&c<0)return std::max({a,b,c});return 0;}
void checkpoint(const fs::path&p,const std::string&token,int nx,int K,int it,const V&F,const V&H){auto q=p.string()+".tmp";std::ofstream f(q,std::ios::binary);char t[128]{};if(token.size()>127)throw std::runtime_error("token length");std::copy(token.begin(),token.end(),t);f.write(t,128);f.write((char*)&nx,4);f.write((char*)&K,4);f.write((char*)&it,4);f.write((char*)F.data(),F.size()*8);f.write((char*)H.data(),H.size()*8);f.close();if(!f)throw std::runtime_error("checkpoint write");fs::rename(q,p);}
int main(int argc,char**argv){try{std::map<std::string,std::string>a;for(int i=1;i<argc;i+=2){if(i+1>=argc)throw std::runtime_error("argument value missing");a[argv[i]]=argv[i+1];}if(a.count("--transport-test")){double worst=0,conservation=0;for(int sign:{-1,1}){const int n=17;double dx=.2,v=sign*2.;V f(n),slope(n),face(n+1);for(int i=0;i<n;i++)f[i]=1+.01*i*dx;for(int i=1;i<n-1;i++)slope[i]=mm(2*(f[i]-f[i-1]),.5*(f[i+1]-f[i-1]),2*(f[i+1]-f[i]));for(int i=2;i<n-2;i++){int up=sign>0?i-1:i+1;double d=std::abs(v)*(f[i]-f[up])/dx+(sign>0?1:-1)*.5*std::abs(v)*(slope[i]-slope[up])/dx;worst=std::max(worst,std::abs(d-v*.01));}for(int i=0;i<n;i++)f[i]=1+.1*std::sin(.3*i);for(int i=1;i<n-1;i++)slope[i]=mm(2*(f[i]-f[i-1]),.5*(f[i+1]-f[i-1]),2*(f[i+1]-f[i]));slope[0]=slope[n-1]=0;for(int i=0;i<=n;i++){int cell=sign>0?i-1:i;face[i]=v*(cell<0?1:cell>=n?f[n-1]:f[cell]+(sign>0?.5:-.5)*slope[cell]);}double sum=0;for(int i=0;i<n;i++)sum+=(face[i+1]-face[i]);conservation=std::max(conservation,std::abs(sum-(face[n]-face[0])));}std::cout<<std::setprecision(17)<<"{\"linear_both_signs_error\":"<<worst<<",\"face_flux_telescoping_error\":"<<conservation<<"}\n";return worst<1e-12&&conservation<1e-12?0:2;}if(a.count("--mach")){double Ma=std::stod(a["--mach"]),gm=1.4;U1=Ma*std::sqrt(gm);R2=(gm+1)*Ma*Ma/((gm-1)*Ma*Ma+2);T2=(2*gm*Ma*Ma-(gm-1))/(gm+1)/R2;U2=U1/R2;EF=U1*(.5*U1*U1+3.5);}if(a.count("--L"))LDOM=std::stod(a["--L"]);if(a.count("--width"))WIDTH=std::stod(a["--width"]);Grid g(a.at("--grid"));fs::path out=a.at("--out");fs::create_directories(out);std::cout<<std::setprecision(17);if(a.count("--kernel")){V F(g.K),H(g.K);std::ifstream f(a["--kernel"]);for(int j=0;j<g.K;j++)if(!(f>>F[j]>>H[j]))throw std::runtime_error("state input");Mom m=moments(F.data(),H.data(),g);std::ofstream o(out/"kernel.csv");o<<std::setprecision(17)<<"F,H,Ft,Ht,Fr,Hr,tau,CF,CH\n";for(int j=0;j<g.K;j++){double ft,ht,fr,hr;targets(m,g.v[j],g.r[j],ft,ht,fr,hr);o<<F[j]<<','<<H[j]<<','<<ft<<','<<ht<<','<<fr<<','<<hr<<','<<m.tau<<','<<((ft-F[j])+(fr-ft)/Z)/m.tau<<','<<((ht-H[j])+(hr-ht)/Z)/m.tau<<'\n';}std::ofstream mo(out/"moments.txt");mo<<std::setprecision(17)<<m.rho<<' '<<m.u<<' '<<m.tt<<' '<<m.tr<<' '<<m.qt<<' '<<m.qr<<' '<<m.tau<<'\n';return 0;}
int nx=std::stoi(a.at("--nx")),maxit=std::stoi(a.at("--iterations")),order=std::stoi(a.at("--order"));double L=LDOM,dx=2*L/nx,dt=std::stod(a.at("--dt")),beta=std::stod(a.at("--beta")),seconds=std::stod(a.at("--seconds"));std::string token=a.at("--token");if(nx<5||!(dt>0&&beta>0&&beta<=1)||(order!=1&&order!=2))throw std::runtime_error("invalid scheme parameters");signal(SIGTERM,stopped);signal(SIGUSR1,stopped);const size_t N=(size_t)nx*g.K;V F(N),H(N),SF(N),SH(N),tau(nx),sF(order==2?N:0),sH(order==2?N:0),left(g.K),right(g.K);for(int j=0;j<g.K;j++){left[j]=M(1,U1,1,g.v[j],g.r[j]);right[j]=a.count("--uniform")?left[j]:M(R2,U2,T2,g.v[j],g.r[j]);}for(int i=0;i<nx;i++){double x=-L+(i+.5)*dx,s=a.count("--uniform")?0:.5*(1+std::tanh(x/WIDTH));for(int j=0;j<g.K;j++){size_t q=(size_t)i*g.K+j;F[q]=(1-s)*left[j]+s*right[j];H[q]=(1-s)*left[j]+s*(a.count("--uniform")?1:T2)*right[j];}}
int iteration=0;fs::path cp=out/"checkpoint.bin";if(fs::exists(cp)){std::ifstream f(cp,std::ios::binary);char t[128];int n,k;f.read(t,128);f.read((char*)&n,4);f.read((char*)&k,4);f.read((char*)&iteration,4);if(std::string(t)!=token||n!=nx||k!=g.K)throw std::runtime_error("resume configuration mismatch");f.read((char*)F.data(),N*8);f.read((char*)H.data(),N*8);if(!f)throw std::runtime_error("resume truncated");}
auto start=std::chrono::steady_clock::now();double change=1,kinmean=1,kinmax=1,fluxmax=1,negative=0;bool converged=false;std::string reason="iteration_budget";std::ofstream hist(out/"history.csv",std::ios::app);if(iteration==0)hist<<"iteration,seconds,absolute_update,discrete_kinetic_mean,discrete_kinetic_max,cell_flux_max,negative_absolute_mass\n";
auto collision=[&](){int failed=0;
#pragma omp parallel for schedule(static)
for(int i=0;i<nx;i++){try{Mom m=moments(F.data()+(size_t)i*g.K,H.data()+(size_t)i*g.K,g);tau[i]=m.tau;for(int j=0;j<g.K;j++){double ft,ht,fr,hr;targets(m,g.v[j],g.r[j],ft,ht,fr,hr);size_t q=(size_t)i*g.K+j;SF[q]=ft+(fr-ft)/Z;SH[q]=ht+(hr-ht)/Z;if(!std::isfinite(SF[q]+SH[q]))throw std::runtime_error("nonfinite targets");}}catch(...){
#pragma omp atomic write
failed=1;}}if(failed)throw std::runtime_error("invalid macroscopic state or target");};
auto diagnostics=[&](){collision();kinmean=0;kinmax=0;fluxmax=0;negative=0;for(int i=0;i<nx;i++){double loss=0,j0=0,j1=0,j2=0;for(int j=0;j<g.K;j++){size_t q=(size_t)i*g.K+j;bool pos=g.v[j]>0;double uf=i==0?left[j]:F[q-g.K],uh=i==0?left[j]:H[q-g.K];if(!pos){uf=i==nx-1?right[j]:F[q+g.K];uh=i==nx-1?(a.count("--uniform")?1:T2)*right[j]:H[q+g.K];}double df=std::abs(g.v[j])*(F[q]-uf)/dx,dh=std::abs(g.v[j])*(H[q]-uh)/dx;if(order==2){double sf=0,sh=0,sp=0,hp=0;if(i>0&&i<nx-1){sf=mm(2*(F[q]-F[q-g.K]),.5*(F[q+g.K]-F[q-g.K]),2*(F[q+g.K]-F[q]));sh=mm(2*(H[q]-H[q-g.K]),.5*(H[q+g.K]-H[q-g.K]),2*(H[q+g.K]-H[q]));}int up=pos?i-1:i+1;if(up>0&&up<nx-1){size_t z=(size_t)up*g.K+j;sp=mm(2*(F[z]-F[z-g.K]),.5*(F[z+g.K]-F[z-g.K]),2*(F[z+g.K]-F[z]));hp=mm(2*(H[z]-H[z-g.K]),.5*(H[z+g.K]-H[z-g.K]),2*(H[z+g.K]-H[z]));}df+=(pos?1:-1)*.5*std::abs(g.v[j])*(sf-sp)/dx;dh+=(pos?1:-1)*.5*std::abs(g.v[j])*(sh-hp)/dx;}double rf=df-(SF[q]-F[q])/tau[i],rh=dh-(SH[q]-H[q])/tau[i];loss+=g.w[j]*(rf*rf+rh*rh)/(R2*R2*T2*T2);j0+=g.w[j]*g.v[j]*F[q]/U1;j1+=g.w[j]*g.v[j]*g.v[j]*F[q]/(U1*U1+1);j2+=g.w[j]*g.v[j]*(.5*(g.v[j]*g.v[j]+g.r[j]*g.r[j])*F[q]+H[q])/EF;negative+=g.w[j]*std::max(-F[q],0.)*dx;}kinmean+=loss/nx;kinmax=std::max(kinmax,loss);fluxmax=std::max(fluxmax,std::max({std::abs(j0-1),std::abs(j1-1),std::abs(j2-1)}));}};
for(;iteration<maxit;){collision();if(order==2){
#pragma omp parallel for schedule(static)
for(int i=0;i<nx;i++)for(int j=0;j<g.K;j++){size_t q=(size_t)i*g.K+j;if(i==0||i==nx-1){sF[q]=sH[q]=0;continue;}sF[q]=mm(2*(F[q]-F[q-g.K]),.5*(F[q+g.K]-F[q-g.K]),2*(F[q+g.K]-F[q]));sH[q]=mm(2*(H[q]-H[q-g.K]),.5*(H[q+g.K]-H[q-g.K]),2*(H[q+g.K]-H[q]));}}
change=0;
#pragma omp parallel for schedule(static) reduction(max:change)
for(int j=0;j<g.K;j++){bool pos=g.v[j]>0;double vv=std::abs(g.v[j]),uf=pos?left[j]:right[j],uh=pos?left[j]:(a.count("--uniform")?1:T2)*right[j];for(int z=0;z<nx;z++){int i=pos?z:nx-1-z;size_t q=(size_t)i*g.K+j;double correctionF=0,correctionH=0;if(order==2){double upF=z==0?0:sF[pos?q-g.K:q+g.K],upH=z==0?0:sH[pos?q-g.K:q+g.K];correctionF=(pos?1:-1)*.5*vv*(sF[q]-upF)/dx;correctionH=(pos?1:-1)*.5*vv*(sH[q]-upH)/dx;}double den=1/dt+1/tau[i]+vv/dx;double nf=(F[q]/dt+SF[q]/tau[i]+vv/dx*uf-correctionF)/den,nh=(H[q]/dt+SH[q]/tau[i]+vv/dx*uh-correctionH)/den;nf=(1-beta)*F[q]+beta*nf;nh=(1-beta)*H[q]+beta*nh;change=std::max(change,std::abs(nf-F[q]));change=std::max(change,std::abs(nh-H[q]));F[q]=nf;H[q]=nh;uf=nf;uh=nh;}}
iteration++;double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();if(iteration%50==0||stop_flag||elapsed>=seconds){diagnostics();hist<<std::setprecision(17)<<iteration<<','<<elapsed<<','<<change<<','<<kinmean<<','<<kinmax<<','<<fluxmax<<','<<negative<<'\n';hist.flush();checkpoint(cp,token,nx,g.K,iteration,F,H);if(change<1e-10&&kinmax<1e-10){converged=true;reason="discrete_stationary";break;}if(stop_flag){reason="signal_checkpoint";break;}if(elapsed>=seconds){reason="wall_budget";break;}}}
diagnostics();std::ofstream prof(out/"profiles.csv");prof<<std::setprecision(17)<<"x,rho,u,Ttr,Trot,T,qt,qr,sigma,Rclosure,Delta,massflux,momentumflux,energyflux\n";for(int i=0;i<nx;i++){Mom m=moments(F.data()+(size_t)i*g.K,H.data()+(size_t)i*g.K,g);double sigma=0,R=0,D=0,j0=0,j1=0,j2=0;for(int j=0;j<g.K;j++){size_t q=(size_t)i*g.K+j;double cx=g.v[j]-m.u,e=cx*cx+g.r[j]*g.r[j],dev=cx*cx-e/3;sigma+=g.w[j]*F[q]*dev;R+=g.w[j]*F[q]*(e-7*m.tt)*dev;D+=g.w[j]*F[q]*e*e;j0+=g.w[j]*g.v[j]*F[q];j1+=g.w[j]*g.v[j]*g.v[j]*F[q];j2+=g.w[j]*g.v[j]*(.5*(g.v[j]*g.v[j]+g.r[j]*g.r[j])*F[q]+H[q]);}prof<<-L+(i+.5)*dx<<','<<m.rho<<','<<m.u<<','<<m.tt<<','<<m.tr<<','<<(3*m.tt+2*m.tr)/5<<','<<m.qt<<','<<m.qr<<','<<sigma<<','<<R<<','<<D-15*m.rho*m.tt*m.tt<<','<<j0<<','<<j1<<','<<j2<<'\n';}checkpoint(cp,token,nx,g.K,iteration,F,H);if(a.count("--nv")){int nv=std::stoi(a["--nv"]),nr=g.K/nv;if(nv*nr!=g.K)throw std::runtime_error("nv does not divide the grid");std::ofstream rb(out/"reduced.bin",std::ios::binary);V row(3*(size_t)nv);for(int i=0;i<nx;i++){for(int jv=0;jv<nv;jv++){double s0=0,s1=0,s2=0;for(int jr=0;jr<nr;jr++){int j=jv*nr+jr;size_t q=(size_t)i*g.K+j;s0+=g.w[j]*F[q];s1+=g.w[j]*H[q];s2+=g.w[j]*g.r[j]*g.r[j]*F[q];}row[3*jv]=s0;row[3*jv+1]=s1;row[3*jv+2]=s2;}rb.write((char*)row.data(),row.size()*8);}std::ofstream vn(out/"vnodes.txt");vn<<std::setprecision(17);for(int jv=0;jv<nv;jv++)vn<<g.v[jv*nr]<<'\n';}std::ofstream status(out/"STATUS.json");status<<std::setprecision(17)<<"{\"reason\":\""<<reason<<"\",\"discrete_stationary\":"<<(converged?"true":"false")<<",\"iteration\":"<<iteration<<",\"kinetic_max\":"<<kinmax<<",\"kinetic_mean\":"<<kinmean<<",\"cell_flux_max\":"<<fluxmax<<",\"negative_absolute_mass\":"<<negative<<",\"nx\":"<<nx<<",\"velocity_count\":"<<g.K<<",\"order\":"<<order<<",\"space_velocity_independence_certified\":false}";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL_CLOSED "<<e.what()<<'\n';return 2;}}
